/**
 * `pnpm banto add resource` の Rust 側のテンプレート（マイグレーション・サービス・REST・
 * Tauri コマンドとそれぞれのテスト）。手本は items（docs/recipes/add-resource.md）。
 *
 * 出力は rustfmt を通す前提で書いている（生成器が最後に `cargo fmt` を呼ぶ）。名前の
 * 長さで折り返しが変わるので、ここでは整形を完全には合わせない。
 */

const GENERATED_NOTE =
	'Generated by `pnpm banto add resource` (docs/recipes/add-resource.md). Ordinary code from\n' +
	'//! here on: edit it by hand, the generator never rewrites it.';

function rustType(field, { input }) {
	switch (field.type) {
		case 'number':
			return field.required ? 'i64' : 'Option<i64>';
		case 'checkbox':
			return 'bool';
		case 'date':
			return input || !field.required ? 'Option<String>' : 'String';
		default:
			return 'String';
	}
}

/** テストに書く、検証を通る値（Rust の式）。 */
function sampleRust(field) {
	switch (field.type) {
		case 'number': {
			const value = sampleNumber(field);
			return field.required ? `${value}` : `Some(${value})`;
		}
		case 'checkbox':
			return 'false';
		case 'date':
			return 'Some("2031-02-03".to_string())';
		default:
			return `"${sampleText(field)}".to_string()`;
	}
}

/** テストに書く、検証を通る値（`json!` の中の式）。 */
function sampleJson(field, text = sampleText(field)) {
	switch (field.type) {
		case 'number':
			return `${sampleNumber(field)}`;
		case 'checkbox':
			return 'false';
		case 'date':
			return '"2031-02-03"';
		default:
			return `"${text}"`;
	}
}

function sampleNumber(field) {
	let value = 1;
	if (field.min !== undefined && value < field.min) value = field.min;
	if (field.max !== undefined && value > field.max) value = field.max;
	return value;
}

function sampleText(field, base = 'Sample') {
	return field.max !== undefined ? base.slice(0, field.max) : base;
}

function jsonBody(spec, overrides = {}) {
	// 自前のキーだけを見る（`constructor`・`toString` という名前の欄で、Object.prototype の
	// 継承値を上書きの値として拾わない）。
	const entries = spec.fields.map(
		(field) =>
			`"${field.name}": ${Object.hasOwn(overrides, field.name) ? overrides[field.name] : sampleJson(field)}`
	);
	return `json!({ ${entries.join(', ')} })`;
}

function sqlColumn(field, dialect) {
	const integer = dialect === 'sqlite' ? 'INTEGER' : 'BIGINT';
	switch (field.type) {
		case 'number':
			return `${field.column} ${integer}${field.required ? ' NOT NULL' : ''}`;
		case 'checkbox':
			return dialect === 'sqlite'
				? `${field.column} INTEGER NOT NULL DEFAULT 0`
				: `${field.column} BOOLEAN NOT NULL DEFAULT FALSE`;
		case 'date':
			return `${field.column} TEXT${field.required ? ' NOT NULL' : ''}`;
		default:
			return `${field.column} TEXT NOT NULL`;
	}
}

export function migrationSql(spec, dialect) {
	const columns = spec.fields.map((field) => `    ${sqlColumn(field, dialect)},`).join('\n');
	if (dialect === 'sqlite')
		return `-- ${spec.name} (generated by \`pnpm banto add resource\`, docs/recipes/add-resource.md).
-- \`updated_at\` is a \`YYYY-MM-DD\` string the app writes; \`version\` is the
-- optimistic-lock counter (1 on create, +1 on every update).
CREATE TABLE ${spec.name} (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
${columns}
    updated_at TEXT NOT NULL,
    version INTEGER NOT NULL DEFAULT 1
);
`;
	return `-- PostgreSQL twin of the migrations-sqlite file of the same name (conventions
-- section 11): the same columns, with strict types (BIGINT for every integer
-- so sqlx decodes it into \`i64\`, BOOLEAN for a checkbox).
CREATE TABLE ${spec.name} (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
${columns}
    updated_at TEXT NOT NULL,
    version BIGINT NOT NULL DEFAULT 1
);
`;
}

function bindExpr(field) {
	switch (field.type) {
		case 'date':
			return 'input.COL.as_deref().filter(|value| !value.is_empty())'.replace('COL', field.column);
		case 'number':
		case 'checkbox':
			return `input.${field.column}`;
		default:
			return `input.${field.column}.trim()`;
	}
}

function validationChecks(spec, used) {
	const blocks = [];
	for (const field of spec.fields) {
		const col = field.column;
		const push = (message) => `errors.push(FieldError {
                field: "${field.name}".to_string(),
                message: ${message},
            });`;
		const branches = [];
		if (field.isText) {
			if (field.required) {
				used.add('required');
				branches.push(`if trimmed.is_empty() {
            ${push('required_message()')}
        }`);
			}
			if (field.max !== undefined) {
				used.add('maxLength');
				// フォーム（@banto/forms の validate.ts）は `str.trim().length`、つまり UTF-16 の
				// 単位で数える。`chars().count()` だと「𠮷」が 1 文字になり、フォームと食い違う。
				branches.push(`if trimmed.encode_utf16().count() > ${field.constants.maxLength} {
            ${push(`max_length_message(${field.constants.maxLength})`)}
        }`);
			}
			if (branches.length > 0)
				blocks.push(`    {
        let trimmed = input.${col}.trim();
        ${branches.join(' else ')}
    }`);
		} else if (field.type === 'number') {
			// 書かなかった側も、安全な整数の範囲（フォームの min/max と同じ値）で必ず見る。
			const min = field.constants.min ?? 'MIN_SAFE_INTEGER';
			const max = field.constants.max ?? 'MAX_SAFE_INTEGER';
			used.add('min').add('max').add(min).add(max);
			branches.push(`if value < ${min} {
            ${push(`min_message(${min})`)}
        }`);
			branches.push(`if value > ${max} {
            ${push(`max_message(${max})`)}
        }`);
			blocks.push(
				field.required
					? `    {
        let value = input.${col};
        ${branches.join(' else ')}
    }`
					: `    if let Some(value) = input.${col} {
        ${branches.join(' else ')}
    }`
			);
		} else if (field.type === 'date') {
			used.add('date');
			if (field.required) used.add('required');
			const missing = field.required
				? `None => {
            ${push('required_message()')}
        }`
				: 'None => {}';
			blocks.push(`    match input.${col}.as_deref().filter(|value| !value.is_empty()) {
        Some(value) if !banto_core::datetime::is_iso_date(value) => {
            ${push('date_message()')}
        }
        Some(_) => {}
        ${missing}
    }`);
		}
	}
	return blocks;
}

function constants(spec, used) {
	const lines = [];
	if (used.has('MIN_SAFE_INTEGER') || used.has('MAX_SAFE_INTEGER'))
		lines.push(
			'// The range of a number field without its own bound: the integers a\n' +
				'// JavaScript number holds exactly (+-(2^53 - 1)), the same as the `min` /\n' +
				'// `max` of the frontend schema. A larger value would already be rounded\n' +
				'// by the time the form sends it.'
		);
	if (used.has('MIN_SAFE_INTEGER'))
		lines.push('const MIN_SAFE_INTEGER: i64 = -9_007_199_254_740_991;');
	if (used.has('MAX_SAFE_INTEGER'))
		lines.push('const MAX_SAFE_INTEGER: i64 = 9_007_199_254_740_991;');
	for (const field of spec.fields) {
		const names = field.constants;
		if (names.maxLength)
			lines.push(
				`/// In UTF-16 code units, as the form counts (\`String.length\`).\nconst ${names.maxLength}: usize = ${field.max};`
			);
		if (names.min) lines.push(`const ${names.min}: i64 = ${field.min};`);
		if (names.max) lines.push(`const ${names.max}: i64 = ${field.max};`);
	}
	return lines.join('\n');
}

const MESSAGE_HELPERS = {
	required: `fn required_message() -> String {
    "必須項目です".to_string()
}`,
	min: `fn min_message(min: i64) -> String {
    format!("{min}以上で入力してください")
}`,
	max: `fn max_message(max: i64) -> String {
    format!("{max}以下で入力してください")
}`,
	maxLength: `fn max_length_message(max: usize) -> String {
    format!("{max}文字以内で入力してください")
}`,
	date: `fn date_message() -> String {
    "日付は YYYY-MM-DD の形で入力してください".to_string()
}`
};

/** 検証で落ちる入力を 1 つ作る（テスト用）。作れなければ null。 */
function invalidInput(spec) {
	for (const field of spec.fields) {
		if (field.isText && field.required)
			return { field, assign: `input.${field.column} = "   ".to_string();` };
		// 上限の 1 つ上（既定の上限なら 2^53。JavaScript でも i64 でも正確に書ける）。
		if (field.type === 'number')
			return {
				field,
				assign: `input.${field.column} = ${field.required ? `${field.max + 1}` : `Some(${field.max + 1})`};`
			};
		// 形は合っているが実在しない日（フォームも断る）。
		if (field.type === 'date')
			return { field, assign: `input.${field.column} = Some("2031-02-30".to_string());` };
	}
	return null;
}

function placeholders(from, count, indent) {
	return Array.from(
		{ length: count },
		(_, index) => `${indent}dialect.placeholder(${from + index}),`
	).join('\n');
}

export function serviceRs(spec) {
	const { name, singular, rowType, inputType, serviceType, fields } = spec;
	const columns = ['id', ...fields.map((field) => field.column), 'updated_at', 'version'].join(
		', '
	);
	const insertColumns = [...fields.map((field) => field.column), 'updated_at'].join(', ');
	const setClause = [...fields.map((field) => `${field.column} = {}`), 'updated_at = {}'].join(
		', '
	);
	const used = new Set();
	const checks = validationChecks(spec, used);
	const hasOptionalNumber = fields.some((field) => field.type === 'number' && !field.required);
	const binds = (indent) => fields.map((field) => `${indent}.bind(${bindExpr(field)})`).join('\n');

	const rowFields = fields
		.map((field) => `    pub ${field.column}: ${rustType(field, { input: false })},`)
		.join('\n');
	const inputFields = fields
		.map((field) => {
			const type = rustType(field, { input: true });
			if (field.type === 'number' && field.required) return `    pub ${field.column}: ${type},`;
			if (field.type === 'number')
				return `    #[serde(default, deserialize_with = "optional_integer")]\n    pub ${field.column}: ${type},`;
			return `    #[serde(default)]\n    pub ${field.column}: ${type},`;
		})
		.join('\n');
	// 監査に残すのは、定義で `audit: true` を付けた欄だけ（conventions §6: 既定で値を記録しない）。
	const audited = fields.filter((field) => field.audit);
	const auditFieldsBody =
		audited.length > 0
			? `    serde_json::json!({
${audited.map((field) => `        "${field.name}": ${singular}.${field.column},`).join('\n')}
    })`
			: `    // No field is marked \`audit: true\` yet, so the log records that a row was
    // written (who, when, which id) and none of its values.
    let _ = ${singular};
    serde_json::json!({})`;
	const columnMap = fields
		.map(
			(field) =>
				`        .${field.isText ? 'text_column' : 'column'}("${field.name}", "${field.column}")`
		)
		.join('\n');
	const title = spec.titleField ? `"name": ${singular}.${spec.titleField.column}, ` : '';
	const titleAfter = spec.titleField ? `"name": after.${spec.titleField.column}, ` : '';
	const constantLines = constants(spec, used);
	const helpers = Object.keys(MESSAGE_HELPERS)
		.filter((key) => used.has(key))
		.map((key) => MESSAGE_HELPERS[key])
		.join('\n\n');
	const validateBody =
		checks.length === 0
			? `    // No rule to check yet: add the checks the frontend schema has here.
    let _ = input;
    Ok(())`
			: `    let mut errors: Vec<FieldError> = Vec::new();

${checks.join('\n\n')}

    if errors.is_empty() {
        Ok(())
    } else {
        Err(BantoError::Validation {
            field_errors: errors,
        })
    }`;
	const optionalInteger = hasOptionalNumber
		? `
/// An optional integer as the form sends it: a number, \`null\`, or \`""\` (an
/// emptied input).
fn optional_integer<'de, D>(deserializer: D) -> Result<Option<i64>, D::Error>
where
    D: serde::Deserializer<'de>,
{
    use serde::de::Error;
    match serde_json::Value::deserialize(deserializer)? {
        serde_json::Value::Null => Ok(None),
        serde_json::Value::String(text) if text.trim().is_empty() => Ok(None),
        serde_json::Value::Number(number) => number
            .as_i64()
            .map(Some)
            .ok_or_else(|| D::Error::custom("整数で入力してください")),
        _ => Err(D::Error::custom("整数で入力してください")),
    }
}
`
		: '';
	const invalid = invalidInput(spec);
	const updateTitle = spec.editField;
	const sampleFields = fields
		.map((field) => `            ${field.column}: ${sampleRust(field)},`)
		.join('\n');
	const n = fields.length;

	return `//! \`${name}\` resource service: the domain logic behind the \`${name}\` resource,
//! called by the REST routes (\`rest/${name}.rs\`) and the Tauri commands
//! (\`src-tauri\`) alike. It knows nothing of axum, tauri, roles or the audit
//! log (conventions section 2): the wiring layers add those. Field names of
//! [\`${inputType}\`] match the frontend schema
//! (\`src/lib/banto/resources/${name}.ts\`) field for field, so a
//! \`BantoError::Validation\` lands on the right form input.
//!
//! ${GENERATED_NOTE}

use banto_core::{BantoError, ${checks.length > 0 ? 'FieldError, ' : ''}ListParams, ListResult};
use banto_server::ServerEvent;
use banto_storage::{ColumnMap, Db};
use serde::{Deserialize, Serialize};
use sqlx::{QueryBuilder, Sqlite};
use tokio::sync::broadcast;

/// A row of the \`${name}\` table, wire-shaped for the frontend (camelCase).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, sqlx::FromRow)]
#[serde(rename_all = "camelCase")]
pub struct ${rowType} {
    pub id: i64,
${rowFields}
    pub updated_at: String,
    /// Row version for optimistic locking: 1 on create, +1 on every update.
    /// A client sends back the version it read; a mismatch is
    /// \`BantoError::Conflict\`.
    pub version: i64,
}

/// The values the audit log may record: **only** the fields marked
/// \`audit: true\` in the field definition this file was generated from
/// (conventions section 6: no value is recorded by default). The three
/// details below (create, update, delete) are all built from this one list,
/// so a field that is not here never reaches the log. Add a field only when
/// everyone who can read the audit log may read its value - never a secret.${
		spec.titleField
			? `\n/// \`detail.name\` is the one field marked \`title: true\` (\`${spec.titleField.name}\`).`
			: ''
	}
fn ${singular}_audit_fields(${singular}: &${rowType}) -> serde_json::Value {
${auditFieldsBody}
}

/// \`detail\` of an \`update\` audit record: \`{ changes: [{ field, before,
/// after }] }\`, the audited fields that changed. Both wirings call this, so
/// REST and Tauri record the same shape (conventions section 1).
pub fn ${singular}_update_detail(before: &${rowType}, after: &${rowType}) -> serde_json::Value {
    let changes = banto_admin_services::audit::diff::diff_changes(
        &${singular}_audit_fields(before),
        &${singular}_audit_fields(after),
        &[],
        &[],
    );
    serde_json::json!({ ${titleAfter}"changes": changes })
}

/// \`detail\` of a \`create\` audit record: the new values as changes from nothing.
pub fn ${singular}_create_detail(${singular}: &${rowType}) -> serde_json::Value {
    let changes = banto_admin_services::audit::diff::diff_changes(
        &serde_json::json!({}),
        &${singular}_audit_fields(${singular}),
        &[],
        &[],
    );
    serde_json::json!({ ${title}"changes": changes })
}

/// \`detail\` of a \`delete\` audit record: the removed values as changes to nothing.
pub fn ${singular}_delete_detail(${singular}: &${rowType}) -> serde_json::Value {
    let changes = banto_admin_services::audit::diff::diff_changes(
        &${singular}_audit_fields(${singular}),
        &serde_json::json!({}),
        &[],
        &[],
    );
    serde_json::json!({ ${title}"changes": changes })
}

/// Create/update payload. \`version\` is the optimistic-lock check of an
/// update: the [\`${rowType}::version\`] the client last read. \`Some\` and
/// different from the stored one -> \`BantoError::Conflict\`; absent -> the
/// update overwrites. \`create\` ignores it.
#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ${inputType} {
${inputFields}
    #[serde(default)]
    pub version: Option<i64>,
}
${optionalInteger}
${constantLines ? `${constantLines}\n\n` : ''}${helpers ? `${helpers}\n\n` : ''}/// Validate the input against the same rules as the frontend schema.
/// Returns every violation, not just the first.
fn validate_input(input: &${inputType}) -> Result<(), BantoError> {
${validateBody}
}

/// Column whitelist for [\`${serviceType}::list\`] (conventions section 6): the
/// only names a sort or a filter may use. The quick search looks in the
/// \`text_column\`s.
fn column_map() -> ColumnMap {
    ColumnMap::new()
        .column("id", "id")
${columnMap}
        .column("updatedAt", "updated_at")
}

const RESOURCE: &str = "${name}";

/// Every column of a row, in [\`${rowType}\`]'s order.
const SELECT_ROWS: &str = "SELECT ${columns} FROM ${name}";
const SELECT_COUNT: &str = "SELECT COUNT(*) FROM ${name}";
const RETURNING: &str = "RETURNING ${columns}";

/// The \`SET version = ...\` expression of every update: +1, back to 1 at
/// \`i64::MAX\` instead of overflowing.
const VERSION_BUMP: &str = "CASE WHEN version < 9223372036854775807 THEN version + 1 ELSE 1 END";

/// The fallback message of a conflict (the client shows its own text).
const CONFLICT_MESSAGE: &str = "他の人が先にこのレコードを変更しました";

/// Optimistic-lock check: \`expected\` is the version the client read (\`None\`
/// = no check). Any other value than the stored one is a \`Conflict\` carrying
/// the current row.
fn check_version(expected: Option<i64>, current: &${rowType}) -> Result<(), BantoError> {
    match expected {
        Some(version) if version != current.version => Err(BantoError::Conflict {
            message: CONFLICT_MESSAGE.to_string(),
            current: serde_json::to_value(current).ok(),
        }),
        _ => Ok(()),
    }
}

/// "Today" as the local date of the machine running the app, \`YYYY-MM-DD\`;
/// stamped into \`updated_at\` (bound as a parameter, never interpolated).
fn local_today() -> String {
    chrono::Local::now()
        .date_naive()
        .format("%Y-%m-%d")
        .to_string()
}

/// \`Clone\` is cheap (a \`Db\` handle and an event sender).
#[derive(Clone)]
pub struct ${serviceType} {
    db: Db,
    events: Option<broadcast::Sender<ServerEvent>>,
    /// Source of the \`updated_at\` date; tests pin it with
    /// [\`${serviceType}::with_today\`].
    today: fn() -> String,
}

impl ${serviceType} {
    pub fn new(db: Db) -> Self {
        Self {
            db,
            events: None,
            today: local_today,
        }
    }

    /// Replace the "today" source used to stamp \`updated_at\` (for tests).
    pub fn with_today(mut self, today: fn() -> String) -> Self {
        self.today = today;
        self
    }

    /// Attach an event sender: every successful write emits
    /// \`ServerEvent::ResourceChanged { resource: "${name}" }\`.
    pub fn with_events(mut self, events: broadcast::Sender<ServerEvent>) -> Self {
        self.events = Some(events);
        self
    }

    /// No receiver (no browser connected) is not an error.
    fn notify_changed(&self) {
        if let Some(tx) = &self.events {
            let _ = tx.send(ServerEvent::ResourceChanged {
                resource: RESOURCE.to_string(),
            });
        }
    }

    pub async fn list(&self, params: ListParams) -> Result<ListResult<${rowType}>, BantoError> {
        let columns = column_map();
        // \`list_query\` is per backend, so the list dispatches on it. Sort and
        // filter names go through \`columns\` only (conventions section 6).
        match &self.db {
            Db::Sqlite(pool) => {
                let mut rows_builder: QueryBuilder<Sqlite> = QueryBuilder::new(SELECT_ROWS);
                banto_storage::list_query::sqlite::apply_list_params(
                    &mut rows_builder,
                    &columns,
                    &params,
                )?;
                let rows: Vec<${rowType}> = rows_builder
                    .build_query_as::<${rowType}>()
                    .fetch_all(pool)
                    .await
                    .map_err(banto_storage::storage_error)?;

                let mut count_builder: QueryBuilder<Sqlite> = QueryBuilder::new(SELECT_COUNT);
                banto_storage::list_query::sqlite::append_list_where(
                    &mut count_builder,
                    &columns,
                    &params,
                )?;
                let total_count: i64 = count_builder
                    .build_query_scalar()
                    .fetch_one(pool)
                    .await
                    .map_err(banto_storage::storage_error)?;

                Ok(ListResult {
                    rows,
                    total_count: total_count as u64,
                })
            }
            #[cfg(feature = "postgres")]
            Db::Postgres(pool) => {
                let mut rows_builder: QueryBuilder<sqlx::Postgres> = QueryBuilder::new(SELECT_ROWS);
                banto_storage::list_query::postgres::apply_list_params(
                    &mut rows_builder,
                    &columns,
                    &params,
                )?;
                let rows: Vec<${rowType}> = rows_builder
                    .build_query_as::<${rowType}>()
                    .fetch_all(pool)
                    .await
                    .map_err(banto_storage::storage_error)?;

                let mut count_builder: QueryBuilder<sqlx::Postgres> =
                    QueryBuilder::new(SELECT_COUNT);
                banto_storage::list_query::postgres::append_list_where(
                    &mut count_builder,
                    &columns,
                    &params,
                )?;
                let total_count: i64 = count_builder
                    .build_query_scalar()
                    .fetch_one(pool)
                    .await
                    .map_err(banto_storage::storage_error)?;

                Ok(ListResult {
                    rows,
                    total_count: total_count as u64,
                })
            }
        }
    }

    pub async fn get(&self, id: i64) -> Result<${rowType}, BantoError> {
        let dialect = self.db.dialect();
        // AssertSqlSafe (here and throughout this impl): only constants of
        // this file and \`dialect.placeholder(n)\` are interpolated, never
        // caller input. Every value is bound with \`.bind(...)\`.
        let sql = format!("{SELECT_ROWS} WHERE id = {}", dialect.placeholder(1));
        match &self.db {
            Db::Sqlite(pool) => {
                sqlx::query_as::<_, ${rowType}>(sqlx::AssertSqlSafe(sql))
                    .bind(id)
                    .fetch_one(pool)
                    .await
            }
            #[cfg(feature = "postgres")]
            Db::Postgres(pool) => {
                sqlx::query_as::<_, ${rowType}>(sqlx::AssertSqlSafe(sql))
                    .bind(id)
                    .fetch_one(pool)
                    .await
            }
        }
        .map_err(|err| banto_storage::not_found(err, RESOURCE, id.to_string()))
    }

    pub async fn create(&self, input: ${inputType}) -> Result<${rowType}, BantoError> {
        validate_input(&input)?;
        let dialect = self.db.dialect();
        // AssertSqlSafe: see the note in \`get\` above.
        let sql = format!(
            "INSERT INTO ${name} (${insertColumns}) VALUES (${Array(n + 1)
							.fill('{}')
							.join(', ')}) {RETURNING}",
${placeholders(1, n + 1, '            ')}
        );
        let today = (self.today)();
        let ${singular} = match &self.db {
            Db::Sqlite(pool) => {
                sqlx::query_as::<_, ${rowType}>(sqlx::AssertSqlSafe(sql))
${binds('                    ')}
                    .bind(&today)
                    .fetch_one(pool)
                    .await
            }
            #[cfg(feature = "postgres")]
            Db::Postgres(pool) => {
                sqlx::query_as::<_, ${rowType}>(sqlx::AssertSqlSafe(sql))
${binds('                    ')}
                    .bind(&today)
                    .fetch_one(pool)
                    .await
            }
        }
        .map_err(banto_storage::storage_error)?;
        self.notify_changed();
        Ok(${singular})
    }

    pub async fn update(&self, id: i64, input: ${inputType}) -> Result<${rowType}, BantoError> {
        self.update_returning_previous(id, input)
            .await
            .map(|(_, ${singular})| ${singular})
    }

    /// Like [\`${serviceType}::update\`], but also returns the row as it was
    /// before (\`(previous, updated)\`), read in the same transaction. The
    /// audit wiring records the difference; the service stays audit-unaware.
    ///
    /// The version check runs on the row read under the same lock as the
    /// write (SQLite \`BEGIN IMMEDIATE\` / PostgreSQL \`FOR UPDATE\`), so two
    /// updates carrying the same version are serialized and the second one
    /// conflicts. An early return drops \`tx\`, which rolls it back.
    pub async fn update_returning_previous(
        &self,
        id: i64,
        input: ${inputType},
    ) -> Result<(${rowType}, ${rowType}), BantoError> {
        validate_input(&input)?;
        let dialect = self.db.dialect();
        let lock = if matches!(self.db, Db::Sqlite(_)) {
            ""
        } else {
            " FOR UPDATE"
        };
        // AssertSqlSafe: see the note in \`get\` above.
        let select_sql = format!("{SELECT_ROWS} WHERE id = {}{lock}", dialect.placeholder(1));
        let sql = format!(
            "UPDATE ${name} SET ${setClause}, version = {VERSION_BUMP} WHERE id = {} {RETURNING}",
${placeholders(1, n + 2, '            ')}
        );
        let today = (self.today)();
        let not_found = |err| banto_storage::not_found(err, RESOURCE, id.to_string());
        let (previous, ${singular}) = match &self.db {
            Db::Sqlite(pool) => {
                // Reserve the writer before reading: a deferred transaction
                // that read first could hit SQLITE_BUSY when it writes.
                let mut tx = pool
                    .begin_with("BEGIN IMMEDIATE")
                    .await
                    .map_err(banto_storage::storage_error)?;
                let previous = sqlx::query_as::<_, ${rowType}>(sqlx::AssertSqlSafe(select_sql))
                    .bind(id)
                    .fetch_one(&mut *tx)
                    .await
                    .map_err(not_found)?;
                check_version(input.version, &previous)?;
                let ${singular} = sqlx::query_as::<_, ${rowType}>(sqlx::AssertSqlSafe(sql))
${binds('                    ')}
                    .bind(&today)
                    .bind(id)
                    .fetch_one(&mut *tx)
                    .await
                    .map_err(not_found)?;
                tx.commit().await.map_err(banto_storage::storage_error)?;
                (previous, ${singular})
            }
            #[cfg(feature = "postgres")]
            Db::Postgres(pool) => {
                // Explicit isolation level: a repeatable-read default would
                // pin the snapshot before the FOR UPDATE wait ends.
                let mut tx = pool
                    .begin_with("BEGIN ISOLATION LEVEL READ COMMITTED")
                    .await
                    .map_err(banto_storage::storage_error)?;
                let previous = sqlx::query_as::<_, ${rowType}>(sqlx::AssertSqlSafe(select_sql))
                    .bind(id)
                    .fetch_one(&mut *tx)
                    .await
                    .map_err(not_found)?;
                check_version(input.version, &previous)?;
                let ${singular} = sqlx::query_as::<_, ${rowType}>(sqlx::AssertSqlSafe(sql))
${binds('                    ')}
                    .bind(&today)
                    .bind(id)
                    .fetch_one(&mut *tx)
                    .await
                    .map_err(not_found)?;
                tx.commit().await.map_err(banto_storage::storage_error)?;
                (previous, ${singular})
            }
        };
        self.notify_changed();
        Ok((previous, ${singular}))
    }

    /// Delete without a version check.
    pub async fn delete(&self, id: i64) -> Result<(), BantoError> {
        self.delete_returning_previous(id, None).await.map(|_| ())
    }

    /// Delete and return the removed row (for the audit record).
    ///
    /// \`expected_version\`: \`Some\` -> the row is read first in the same
    /// transaction and a different stored version is \`BantoError::Conflict\`
    /// with nothing deleted. A missing id is \`NotFound\` either way.
    pub async fn delete_returning_previous(
        &self,
        id: i64,
        expected_version: Option<i64>,
    ) -> Result<${rowType}, BantoError> {
        let dialect = self.db.dialect();
        let lock = if matches!(self.db, Db::Sqlite(_)) {
            ""
        } else {
            " FOR UPDATE"
        };
        // AssertSqlSafe: see the note in \`get\` above.
        let sql = format!(
            "DELETE FROM ${name} WHERE id = {} {RETURNING}",
            dialect.placeholder(1)
        );
        let check_sql = format!("{SELECT_ROWS} WHERE id = {}{lock}", dialect.placeholder(1));
        let missing = || BantoError::NotFound {
            resource: RESOURCE.to_string(),
            id: id.to_string(),
        };
        let ${singular} = match &self.db {
            Db::Sqlite(pool) => {
                let mut tx = pool
                    .begin_with("BEGIN IMMEDIATE")
                    .await
                    .map_err(banto_storage::storage_error)?;
                if expected_version.is_some() {
                    let current = sqlx::query_as::<_, ${rowType}>(sqlx::AssertSqlSafe(check_sql))
                        .bind(id)
                        .fetch_optional(&mut *tx)
                        .await
                        .map_err(banto_storage::storage_error)?
                        .ok_or_else(missing)?;
                    check_version(expected_version, &current)?;
                }
                let ${singular} = sqlx::query_as::<_, ${rowType}>(sqlx::AssertSqlSafe(sql))
                    .bind(id)
                    .fetch_optional(&mut *tx)
                    .await
                    .map_err(banto_storage::storage_error)?;
                tx.commit().await.map_err(banto_storage::storage_error)?;
                ${singular}
            }
            #[cfg(feature = "postgres")]
            Db::Postgres(pool) => {
                let mut tx = pool
                    .begin_with("BEGIN ISOLATION LEVEL READ COMMITTED")
                    .await
                    .map_err(banto_storage::storage_error)?;
                if expected_version.is_some() {
                    let current = sqlx::query_as::<_, ${rowType}>(sqlx::AssertSqlSafe(check_sql))
                        .bind(id)
                        .fetch_optional(&mut *tx)
                        .await
                        .map_err(banto_storage::storage_error)?
                        .ok_or_else(missing)?;
                    check_version(expected_version, &current)?;
                }
                let ${singular} = sqlx::query_as::<_, ${rowType}>(sqlx::AssertSqlSafe(sql))
                    .bind(id)
                    .fetch_optional(&mut *tx)
                    .await
                    .map_err(banto_storage::storage_error)?;
                tx.commit().await.map_err(banto_storage::storage_error)?;
                ${singular}
            }
        };
        let ${singular} = ${singular}.ok_or_else(missing)?;
        self.notify_changed();
        Ok(${singular})
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_input() -> ${inputType} {
        ${inputType} {
${sampleFields}
            version: None,
        }
    }

    async fn service() -> ${serviceType} {
        let db = crate::db::init_db_memory().await.expect("init_db_memory");
        ${serviceType}::new(db).with_today(|| "2031-02-03".to_string())
    }

    #[tokio::test]
    async fn create_then_get_and_list_round_trip() {
        let service = service().await;
        let created = service.create(sample_input()).await.expect("create");
        assert_eq!(created.version, 1);
        assert_eq!(created.updated_at, "2031-02-03");

        let fetched = service.get(created.id).await.expect("get");
        assert_eq!(fetched, created);

        let listed = service.list(ListParams::default()).await.expect("list");
        assert_eq!(listed.total_count, 1);
        assert_eq!(listed.rows, vec![created]);
    }

    #[tokio::test]
    async fn update_bumps_the_version_and_a_stale_version_conflicts() {
        let service = service().await;
        let created = service.create(sample_input()).await.expect("create");

        let mut input = sample_input();
        input.version = Some(created.version);
${updateTitle ? `        input.${updateTitle.column} = "${sampleText(updateTitle, 'Changed')}".to_string();\n` : ''}        let (previous, updated) = service
            .update_returning_previous(created.id, input)
            .await
            .expect("update");
        assert_eq!(previous, created);
        assert_eq!(updated.version, 2);
${updateTitle ? `        assert_eq!(updated.${updateTitle.column}, "${sampleText(updateTitle, 'Changed')}");\n` : ''}
        // The version read before that update is stale now.
        let mut stale = sample_input();
        stale.version = Some(created.version);
        let result = service.update(created.id, stale).await;
        assert!(
            matches!(result, Err(BantoError::Conflict { .. })),
            "{result:?}"
        );

        // No version: the update overwrites.
        let overwritten = service
            .update(created.id, sample_input())
            .await
            .expect("update without a version");
        assert_eq!(overwritten.version, 3);
    }

    #[tokio::test]
    async fn delete_checks_the_version_and_a_missing_id_is_not_found() {
        let service = service().await;
        let created = service.create(sample_input()).await.expect("create");

        let result = service
            .delete_returning_previous(created.id, Some(created.version + 1))
            .await;
        assert!(
            matches!(result, Err(BantoError::Conflict { .. })),
            "{result:?}"
        );
        assert!(service.get(created.id).await.is_ok(), "row must remain");

        let removed = service
            .delete_returning_previous(created.id, Some(created.version))
            .await
            .expect("delete");
        assert_eq!(removed, created);

        let result = service.delete(created.id).await;
        assert!(
            matches!(result, Err(BantoError::NotFound { .. })),
            "{result:?}"
        );
    }
${
	invalid
		? `
    #[tokio::test]
    async fn invalid_input_is_a_validation_error_on_the_field() {
        let service = service().await;
        let mut input = sample_input();
        ${invalid.assign}
        match service.create(input).await {
            Err(BantoError::Validation { field_errors }) => {
                assert!(
                    field_errors.iter().any(|e| e.field == "${invalid.field.name}"),
                    "{field_errors:?}"
                );
            }
            other => panic!("expected a validation error, got {other:?}"),
        }
    }
`
		: ''
}${auditTest(spec)}}
`;
}

/**
 * 生成した Rust のテスト: 作成・更新・削除の監査の detail に、`audit: true` の欄（と `title` の
 * 欄の `name`）だけが出ること。全部の欄を前後で違う値にした 2 行から 3 つの detail を作る。
 */
function auditTest(spec) {
	const { singular, rowType, fields, titleField } = spec;
	const value = (field, index, side) => {
		const after = side === 'after';
		switch (field.type) {
			case 'number': {
				const number = 7_000_000 + index * 2 + (after ? 1 : 0);
				return { rust: field.required ? `${number}` : `Some(${number})`, text: null };
			}
			case 'checkbox':
				return { rust: `${after}`, text: null };
			case 'date': {
				const text = `${1900 + index}-0${after ? 2 : 1}-01`;
				return {
					rust: field.required ? `"${text}".to_string()` : `Some("${text}".to_string())`,
					text
				};
			}
			default: {
				const text = `audit-${side}-${field.column}`;
				return { rust: `"${text}".to_string()`, text };
			}
		}
	};
	const row = (side, updatedAt, version) => `${rowType} {
            id: 7,
${fields.map((field, index) => `            ${field.column}: ${value(field, index, side).rust},`).join('\n')}
            updated_at: "${updatedAt}".to_string(),
            version: ${version},
        }`;
	const audited = fields
		.filter((field) => field.audit)
		.map((field) => field.name)
		.sort();
	// 監査対象でない欄の値（文字列で探せるもの）。`title` の欄の値は `detail.name` に出るので除く。
	const hidden = fields.flatMap((field, index) =>
		field.audit || field === titleField
			? []
			: ['before', 'after']
					.map((side) => value(field, index, side).text)
					.filter((text) => text !== null)
	);
	const titleIndex = titleField ? fields.indexOf(titleField) : -1;
	const name = (side) =>
		titleField ? `, Some("${value(titleField, titleIndex, side).text}")` : ', None::<&str>';
	const hiddenCheck =
		hidden.length > 0
			? `
            // JSON text of the whole detail, searched for the quoted values.
            let text = detail.to_string();
            for value in [
${hidden.map((text) => `                "\\"${text}\\"",`).join('\n')}
            ] {
                assert!(!text.contains(value), "{value} leaked into {text}");
            }`
			: '';
	return `
    /// Conventions section 6: an audit detail holds the fields marked
    /// \`audit: true\` (plus \`name\`, the field marked \`title: true\`) and no
    /// other value of the row - on create, on update and on delete.
    #[test]
    fn audit_details_hold_only_the_fields_marked_for_audit() {
        // Every field differs between the two rows, so an unmarked field
        // that leaked into a detail would show up as a change.
        let before = ${row('before', '2031-02-03', 1)};
        let after = ${row('after', '2031-02-04', 2)};
        let audited: [&str; ${audited.length}] = [${audited.map((field) => `"${field}"`).join(', ')}];

        for (detail, name) in [
            (${singular}_create_detail(&before)${name('before')}),
            (${singular}_update_detail(&before, &after)${name('after')}),
            (${singular}_delete_detail(&before)${name('before')}),
        ] {
            let object = detail.as_object().expect("the detail is an object");
            for key in object.keys() {
                assert!(key == "changes" || key == "name", "{key} in {detail}");
            }
            assert_eq!(
                object.get("name").and_then(|value| value.as_str()),
                name,
                "{detail}"
            );
            let mut changed: Vec<&str> = detail["changes"]
                .as_array()
                .expect("changes")
                .iter()
                .map(|change| change["field"].as_str().expect("field"))
                .collect();
            changed.sort_unstable();
            assert_eq!(changed, audited, "{detail}");${hiddenCheck}
        }
    }
`;
}

export function restRs(spec) {
	const { name, singular, rowType, inputType, serviceType } = spec;
	const changed = spec.editField
		? { [spec.editField.name]: `"${sampleText(spec.editField, 'Changed')}"` }
		: {};
	return `//! REST routes of the \`${name}\` resource (\`/api/${name}/*\`): the LAN-browser
//! twin of \`src-tauri\`'s \`${name}_*\` commands. Reads need a session (any
//! role); writes need \`editor\` and record one audit entry each, the same as
//! the commands (conventions section 1). \`rest::resources_router\` mounts
//! [\`${name}_router\`].
//!
//! ${GENERATED_NOTE}

use axum::extract::{Path, State};
use axum::http::StatusCode;
use axum::middleware;
use axum::routing::{get, post};
use axum::{Json, Router};
use banto_core::{ListParams, ListResult};
use banto_server::routes::{record_write, require_role_at_least, AuditActor, RoleGuard};
use banto_server::{require_auth, ApiError, AuthState};

use crate::audit::AuditLogService;
use crate::${name}::{
    ${singular}_create_detail, ${singular}_delete_detail, ${singular}_update_detail, ${rowType},
    ${inputType}, ${serviceType},
};
use crate::users::Role;

async fn ${name}_list(
    State(${name}): State<${serviceType}>,
    Json(params): Json<ListParams>,
) -> Result<Json<ListResult<${rowType}>>, ApiError> {
    Ok(Json(${name}.list(params).await?))
}

async fn ${name}_get(
    State(${name}): State<${serviceType}>,
    Path(id): Path<i64>,
) -> Result<Json<${rowType}>, ApiError> {
    Ok(Json(${name}.get(id).await?))
}

/// State of the write handlers: the service, plus the audit log
/// \`record_write\` writes to once the change has succeeded. The actor of the
/// entry is the snapshot \`require_auth\` made when it authorized the request
/// (\`Extension<AuditActor>\`), never a second look at the token. Reads are not
/// audited.
#[derive(Clone)]
struct WriteState {
    ${name}: ${serviceType},
    audit: AuditLogService,
}

async fn ${name}_create(
    State(state): State<WriteState>,
    axum::Extension(actor): axum::Extension<AuditActor>,
    Json(input): Json<${inputType}>,
) -> Result<Json<${rowType}>, ApiError> {
    let ${singular} = state.${name}.create(input).await?;
    record_write(
        &state.audit,
        &actor,
        "create",
        "${name}",
        Some(&${singular}.id.to_string()),
        Some(${singular}_create_detail(&${singular})),
    )
    .await;
    Ok(Json(${singular}))
}

async fn ${name}_update(
    State(state): State<WriteState>,
    axum::Extension(actor): axum::Extension<AuditActor>,
    Path(id): Path<i64>,
    Json(input): Json<${inputType}>,
) -> Result<Json<${rowType}>, ApiError> {
    let (previous, ${singular}) = state.${name}.update_returning_previous(id, input).await?;
    record_write(
        &state.audit,
        &actor,
        "update",
        "${name}",
        Some(&${singular}.id.to_string()),
        Some(${singular}_update_detail(&previous, &${singular})),
    )
    .await;
    Ok(Json(${singular}))
}

/// \`?version=N\` of the delete: the optimistic-lock check (a different stored
/// version is a \`409\` \`conflict\`, nothing deleted). A query string, since
/// some clients and proxies drop a DELETE body.
#[derive(Debug, Default, serde::Deserialize)]
struct DeleteQuery {
    version: Option<i64>,
}

async fn ${name}_delete(
    State(state): State<WriteState>,
    axum::Extension(actor): axum::Extension<AuditActor>,
    Path(id): Path<i64>,
    query: Result<axum::extract::Query<DeleteQuery>, axum::extract::rejection::QueryRejection>,
) -> Result<StatusCode, ApiError> {
    // A malformed \`version\` answers the usual \`bad_request\` body, not
    // axum's plain-text rejection.
    let axum::extract::Query(query) =
        query.map_err(|err| banto_core::BantoError::BadRequest(err.body_text()))?;
    let ${singular} = state
        .${name}
        .delete_returning_previous(id, query.version)
        .await?;
    record_write(
        &state.audit,
        &actor,
        "delete",
        "${name}",
        Some(&id.to_string()),
        Some(${singular}_delete_detail(&${singular})),
    )
    .await;
    Ok(StatusCode::NO_CONTENT)
}

/// Read-only routes: any authenticated role (\`require_auth\` alone).
fn ${name}_read_router(${name}: ${serviceType}, auth: AuthState) -> Router {
    Router::new()
        .route("/api/${name}/list", post(${name}_list))
        .route("/api/${name}/{id}", get(${name}_get))
        .with_state(${name})
        .layer(middleware::from_fn_with_state(auth, require_auth))
}

/// Mutating routes: \`editor\` and up. \`require_auth\` is layered last so it
/// runs first: a request needs a valid session before its role is looked at.
/// A role too low is a \`403\` plus a \`denied\` audit entry (\`RoleGuard\`).
fn ${name}_write_router(${name}: ${serviceType}, audit: AuditLogService, auth: AuthState) -> Router {
    let state = WriteState {
        ${name},
        audit: audit.clone(),
    };
    Router::new()
        .route("/api/${name}", post(${name}_create))
        .route(
            "/api/${name}/{id}",
            axum::routing::put(${name}_update).delete(${name}_delete),
        )
        .with_state(state)
        .layer(middleware::from_fn_with_state(
            RoleGuard {
                auth: auth.clone(),
                min: Role::Editor,
                resource: "${name}",
                audit,
            },
            require_role_at_least,
        ))
        .layer(middleware::from_fn_with_state(auth, require_auth))
}

/// \`/api/${name}/*\`: the read (any role) and write (\`editor\`+) routers merged.
pub(super) fn ${name}_router(${name}: ${serviceType}, audit: AuditLogService, auth: AuthState) -> Router {
    ${name}_read_router(${name}.clone(), auth.clone()).merge(${name}_write_router(${name}, audit, auth))
}

#[cfg(test)]
mod tests {
    //! The REST half of the two-path symmetry (conventions section 1): the
    //! role floor, the \`denied\` entry and the audit entries of each write.
    //! The Tauri half is in \`src-tauri/src/lib.rs\` (\`${name}_*\` tests).

    use super::*;
    use axum::body::Body;
    use axum::http::Request;
    use banto_server::{Identity, SessionValidation};
    use serde_json::{json, Value};
    use tokio::sync::broadcast;
    use tower::ServiceExt;

    /// The routes as the servers mount them (\`rest::resources_router\`), the
    /// audit log behind them, and one bearer token per role.
    async fn router_with_role_tokens() -> (Router, AuditLogService, String, String, String) {
        let db = crate::db::init_db_memory().await.expect("init_db_memory");
        let (events, _rx) = broadcast::channel(16);
        let audit = AuditLogService::new(db.clone());
        // Each account's role is its username; the password is the same.
        let auth = AuthState::new(
            |username: String, password: String| {
                Box::pin(async move {
                    let known = matches!(username.as_str(), "admin" | "editor" | "viewer");
                    (known && password == "password123").then(|| Identity {
                        id: username.clone(),
                        name: username.clone(),
                        role: username,
                    })
                })
            },
            SessionValidation::DisabledNoRevocation,
        );
        let admin = auth.login("admin", "password123").await.expect("admin");
        let editor = auth.login("editor", "password123").await.expect("editor");
        let viewer = auth.login("viewer", "password123").await.expect("viewer");
        let router = crate::rest::resources_router(
            crate::resources::AppResources::new(&db, &events),
            audit.clone(),
            auth,
        );
        (router, audit, admin, editor, viewer)
    }

    fn request(method: &str, path: &str, token: Option<&str>, body: Option<Value>) -> Request<Body> {
        let mut builder = Request::builder()
            .method(method)
            .uri(path)
            .header("X-Banto-Client", "banto");
        if let Some(token) = token {
            builder = builder.header("Authorization", format!("Bearer {token}"));
        }
        match body {
            Some(body) => builder
                .header("content-type", "application/json")
                .body(Body::from(body.to_string()))
                .unwrap(),
            None => builder.body(Body::empty()).unwrap(),
        }
    }

    async fn body_json(response: axum::response::Response) -> Value {
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .expect("body");
        serde_json::from_slice(&bytes).expect("json body")
    }

    fn sample_body() -> Value {
        ${jsonBody(spec)}
    }

    async fn create(router: &Router, token: &str) -> Value {
        let response = router
            .clone()
            .oneshot(request("POST", "/api/${name}", Some(token), Some(sample_body())))
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        body_json(response).await
    }

    /// \`(action, result, actor, origin)\` of every \`${name}\` audit entry, oldest first.
    async fn audit_entries(audit: &AuditLogService) -> Vec<(String, String, String, String)> {
        let mut rows = audit
            .list(ListParams::default())
            .await
            .expect("audit list")
            .rows;
        rows.sort_by_key(|row| row.id);
        rows.into_iter()
            .filter(|row| row.resource == "${name}")
            .map(|row| {
                (
                    row.action,
                    row.result,
                    row.actor_username.unwrap_or_default(),
                    row.origin,
                )
            })
            .collect()
    }

    #[tokio::test]
    async fn without_a_session_every_route_is_unauthorized_and_nothing_is_audited() {
        let (router, audit, _admin, _editor, _viewer) = router_with_role_tokens().await;
        for (method, path, body) in [
            ("POST", "/api/${name}/list", Some(json!({}))),
            ("GET", "/api/${name}/1", None),
            ("POST", "/api/${name}", Some(sample_body())),
            ("PUT", "/api/${name}/1", Some(sample_body())),
            ("DELETE", "/api/${name}/1", None),
        ] {
            let response = router
                .clone()
                .oneshot(request(method, path, None, body))
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::UNAUTHORIZED, "{method} {path}");
        }
        assert!(audit_entries(&audit).await.is_empty());
    }

    #[tokio::test]
    async fn viewer_can_read_but_a_write_is_forbidden_and_recorded_as_denied() {
        let (router, audit, _admin, editor, viewer) = router_with_role_tokens().await;
        let created = create(&router, &editor).await;
        let id = created["id"].as_i64().expect("id");

        let response = router
            .clone()
            .oneshot(request("POST", "/api/${name}/list", Some(&viewer), Some(json!({}))))
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let response = router
            .clone()
            .oneshot(request("GET", &format!("/api/${name}/{id}"), Some(&viewer), None))
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(body_json(response).await, created);

        for (method, path, body) in [
            ("POST", "/api/${name}".to_string(), Some(sample_body())),
            ("PUT", format!("/api/${name}/{id}"), Some(sample_body())),
            ("DELETE", format!("/api/${name}/{id}"), None),
        ] {
            let response = router
                .clone()
                .oneshot(request(method, &path, Some(&viewer), body))
                .await
                .unwrap();
            assert_eq!(response.status(), StatusCode::FORBIDDEN, "{method} {path}");
            assert_eq!(body_json(response).await["kind"], "forbidden");
        }

        let entries = audit_entries(&audit).await;
        let denied: Vec<_> = entries.iter().filter(|entry| entry.0 == "denied").collect();
        assert_eq!(denied.len(), 3, "{entries:?}");
        for entry in denied {
            assert_eq!(
                (entry.1.as_str(), entry.2.as_str(), entry.3.as_str()),
                ("denied", "viewer", "rest")
            );
        }
        // Nothing but the editor's create went through.
        assert_eq!(
            entries.iter().filter(|entry| entry.1 == "ok").count(),
            1,
            "{entries:?}"
        );
    }

    #[tokio::test]
    async fn editor_writes_are_recorded_once_each_with_origin_rest() {
        let (router, audit, _admin, editor, _viewer) = router_with_role_tokens().await;
        let created = create(&router, &editor).await;
        let id = created["id"].as_i64().expect("id");
        assert_eq!(created["version"], 1);

        let mut body = ${jsonBody(spec, changed)};
        body["version"] = json!(1);
        let response = router
            .clone()
            .oneshot(request("PUT", &format!("/api/${name}/{id}"), Some(&editor), Some(body)))
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        assert_eq!(body_json(response).await["version"], 2);

        let response = router
            .clone()
            .oneshot(request(
                "DELETE",
                &format!("/api/${name}/{id}?version=2"),
                Some(&editor),
                None,
            ))
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::NO_CONTENT);

        let entries = audit_entries(&audit).await;
        let expected: Vec<(String, String, String, String)> = ["create", "update", "delete"]
            .into_iter()
            .map(|action| {
                (
                    action.to_string(),
                    "ok".to_string(),
                    "editor".to_string(),
                    "rest".to_string(),
                )
            })
            .collect();
        assert_eq!(entries, expected);
    }

    #[tokio::test]
    async fn a_stale_version_is_a_conflict_and_is_not_audited() {
        let (router, audit, _admin, editor, _viewer) = router_with_role_tokens().await;
        let created = create(&router, &editor).await;
        let id = created["id"].as_i64().expect("id");

        let mut body = sample_body();
        body["version"] = json!(99);
        let response = router
            .clone()
            .oneshot(request("PUT", &format!("/api/${name}/{id}"), Some(&editor), Some(body)))
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::CONFLICT);
        let conflict = body_json(response).await;
        assert_eq!(conflict["kind"], "conflict");

        let response = router
            .clone()
            .oneshot(request(
                "DELETE",
                &format!("/api/${name}/{id}?version=99"),
                Some(&editor),
                None,
            ))
            .await
            .unwrap();
        assert_eq!(response.status(), StatusCode::CONFLICT);

        // Only the create is in the log: a conflict changed nothing.
        let actions: Vec<String> = audit_entries(&audit)
            .await
            .into_iter()
            .map(|entry| entry.0)
            .collect();
        assert_eq!(actions, vec!["create".to_string()]);
    }
}
`;
}

/** rest/mod.rs の Route table（doc）に足す行。verify-architecture の一次情報。 */
export function routeTableRows(spec) {
	const { name, rowType, inputType } = spec;
	return [
		`//! | POST   | \`/api/${name}/list\` | \`ListParams\` | \`ListResult<${rowType}>\` (any role) |`,
		`//! | GET    | \`/api/${name}/{id}\` | - | \`${rowType}\` (any role) |`,
		`//! | POST   | \`/api/${name}\` | \`${inputType}\` | \`${rowType}\` (editor+) |`,
		`//! | PUT    | \`/api/${name}/{id}\` | \`${inputType}\` | \`${rowType}\` (editor+) |`,
		`//! | DELETE | \`/api/${name}/{id}\` | - | 204 (editor+) |`
	].join('\n');
}

export function tauriCommands(spec) {
	const { name, singular, rowType, inputType } = spec;
	const core = `admin_template_core::${name}`;
	return `// --- ${name}: generated by \`pnpm banto add resource\`, ordinary code from here on ---
//
// The Tauri twins of REST's \`/api/${name}/*\` (\`core/src/rest/${name}.rs\`): the
// same role floor (\`require_role\` mirrors \`RoleGuard\`) and the same audit
// entries, with \`origin: "tauri"\` (conventions section 1). Each write has a
// \`_body\` over a plain \`&AppState\` so the tests below can call it.

/// Read-only: any authenticated role.
#[tauri::command]
async fn ${name}_list(
    state: State<'_, AppState>,
    params: banto_core::ListParams,
) -> Result<banto_core::ListResult<${core}::${rowType}>, BantoError> {
    require_role(&state, Role::Viewer, "${name}").await?;
    state.resources.${name}.list(params).await
}

#[tauri::command]
async fn ${name}_get(
    state: State<'_, AppState>,
    id: i64,
) -> Result<${core}::${rowType}, BantoError> {
    require_role(&state, Role::Viewer, "${name}").await?;
    state.resources.${name}.get(id).await
}

async fn ${name}_create_body(
    state: &AppState,
    values: ${core}::${inputType},
) -> Result<${core}::${rowType}, BantoError> {
    let actor = require_role(state, Role::Editor, "${name}").await?;
    let ${singular} = state.resources.${name}.create(values).await?;
    record_ok(
        &state.audit,
        &actor,
        "create",
        "${name}",
        Some(&${singular}.id.to_string()),
        Some(${core}::${singular}_create_detail(&${singular})),
    )
    .await;
    Ok(${singular})
}

#[tauri::command]
async fn ${name}_create(
    state: State<'_, AppState>,
    values: ${core}::${inputType},
) -> Result<${core}::${rowType}, BantoError> {
    ${name}_create_body(&state, values).await
}

async fn ${name}_update_body(
    state: &AppState,
    id: i64,
    values: ${core}::${inputType},
) -> Result<${core}::${rowType}, BantoError> {
    let actor = require_role(state, Role::Editor, "${name}").await?;
    let (previous, ${singular}) = state
        .resources
        .${name}
        .update_returning_previous(id, values)
        .await?;
    record_ok(
        &state.audit,
        &actor,
        "update",
        "${name}",
        Some(&${singular}.id.to_string()),
        Some(${core}::${singular}_update_detail(&previous, &${singular})),
    )
    .await;
    Ok(${singular})
}

#[tauri::command]
async fn ${name}_update(
    state: State<'_, AppState>,
    id: i64,
    values: ${core}::${inputType},
) -> Result<${core}::${rowType}, BantoError> {
    ${name}_update_body(&state, id, values).await
}

/// \`version\` is the optimistic-lock check, the same as REST's
/// \`DELETE /api/${name}/{id}?version=N\`: a different stored version is a
/// \`conflict\`, and nothing is deleted or audited.
async fn ${name}_delete_body(
    state: &AppState,
    id: i64,
    version: Option<i64>,
) -> Result<(), BantoError> {
    let actor = require_role(state, Role::Editor, "${name}").await?;
    let ${singular} = state
        .resources
        .${name}
        .delete_returning_previous(id, version)
        .await?;
    record_ok(
        &state.audit,
        &actor,
        "delete",
        "${name}",
        Some(&id.to_string()),
        Some(${core}::${singular}_delete_detail(&${singular})),
    )
    .await;
    Ok(())
}

#[tauri::command]
async fn ${name}_delete(
    state: State<'_, AppState>,
    id: i64,
    version: Option<i64>,
) -> Result<(), BantoError> {
    ${name}_delete_body(&state, id, version).await
}
`;
}

export function tauriHandlers(spec) {
	return ['list', 'get', 'create', 'update', 'delete']
		.map((verb) => `            ${spec.name}_${verb},`)
		.join('\n');
}

export function tauriTests(spec) {
	const { name, inputType } = spec;
	const core = `admin_template_core::${name}`;
	const sampleFields = spec.fields
		.map((field) => `        ${field.column}: ${sampleRust(field)},`)
		.join('\n');
	return `// --- ${name}: generated by \`pnpm banto add resource\` ---
//
// The Tauri half of the two-path symmetry (conventions section 1); the
// REST half is in \`core/src/rest/${name}.rs\`.

/// An \`AppState\` whose session is a fresh account of \`role\`.
async fn ${name}_state_as(role: Role) -> AppState {
    let state = app_state().await;
    let user = state
        .users
        .create_user("actor", "password123", "Actor", role)
        .await
        .expect("create_user");
    state.set_session_for_test(Some(DesktopSession::Account(user)));
    state
}

fn ${name}_sample_input() -> ${core}::${inputType} {
    ${core}::${inputType} {
${sampleFields}
        version: None,
    }
}

/// \`(action, result, origin)\` of every \`${name}\` audit entry, oldest first.
async fn ${name}_audit_entries(state: &AppState) -> Vec<(String, String, String)> {
    let mut rows = state
        .audit
        .list(banto_core::ListParams::default())
        .await
        .expect("audit list")
        .rows;
    rows.sort_by_key(|row| row.id);
    rows.into_iter()
        .filter(|row| row.resource == "${name}")
        .map(|row| (row.action, row.result, row.origin))
        .collect()
}

#[tokio::test]
async fn ${name}_without_a_session_is_unauthorized_and_not_audited() {
    let state = app_state().await;
    let result = ${name}_create_body(&state, ${name}_sample_input()).await;
    assert!(matches!(result, Err(BantoError::Unauthorized)), "{result:?}");
    assert!(${name}_audit_entries(&state).await.is_empty());
}

#[tokio::test]
async fn ${name}_viewer_writes_are_forbidden_and_recorded_as_denied() {
    let state = ${name}_state_as(Role::Viewer).await;
    let seeded = state
        .resources
        .${name}
        .create(${name}_sample_input())
        .await
        .expect("seed");

    let result = ${name}_create_body(&state, ${name}_sample_input()).await;
    assert!(matches!(result, Err(BantoError::Forbidden)), "{result:?}");
    let result = ${name}_update_body(&state, seeded.id, ${name}_sample_input()).await;
    assert!(matches!(result, Err(BantoError::Forbidden)), "{result:?}");
    let result = ${name}_delete_body(&state, seeded.id, None).await;
    assert!(matches!(result, Err(BantoError::Forbidden)), "{result:?}");

    assert!(
        state.resources.${name}.get(seeded.id).await.is_ok(),
        "row must remain"
    );
    let denied = (
        "denied".to_string(),
        "denied".to_string(),
        "tauri".to_string(),
    );
    assert_eq!(
        ${name}_audit_entries(&state).await,
        vec![denied.clone(), denied.clone(), denied]
    );
}

#[tokio::test]
async fn ${name}_editor_writes_are_recorded_once_each_with_origin_tauri() {
    let state = ${name}_state_as(Role::Editor).await;
    let created = ${name}_create_body(&state, ${name}_sample_input())
        .await
        .expect("create");
    let mut input = ${name}_sample_input();
    input.version = Some(created.version);
    let updated = ${name}_update_body(&state, created.id, input)
        .await
        .expect("update");
    assert_eq!(updated.version, created.version + 1);
    ${name}_delete_body(&state, created.id, Some(updated.version))
        .await
        .expect("delete");

    let expected: Vec<(String, String, String)> = ["create", "update", "delete"]
        .into_iter()
        .map(|action| (action.to_string(), "ok".to_string(), "tauri".to_string()))
        .collect();
    assert_eq!(${name}_audit_entries(&state).await, expected);
}

#[tokio::test]
async fn ${name}_stale_version_conflicts_without_an_audit_entry() {
    let state = ${name}_state_as(Role::Editor).await;
    let created = ${name}_create_body(&state, ${name}_sample_input())
        .await
        .expect("create");

    let mut stale = ${name}_sample_input();
    stale.version = Some(created.version + 1);
    let result = ${name}_update_body(&state, created.id, stale).await;
    assert!(
        matches!(result, Err(BantoError::Conflict { .. })),
        "{result:?}"
    );
    let result = ${name}_delete_body(&state, created.id, Some(created.version + 1)).await;
    assert!(
        matches!(result, Err(BantoError::Conflict { .. })),
        "{result:?}"
    );

    let actions: Vec<String> = ${name}_audit_entries(&state)
        .await
        .into_iter()
        .map(|entry| entry.0)
        .collect();
    assert_eq!(actions, vec!["create".to_string()]);
}
`;
}
